function centerSelectedSite(){const s=currentSite();if(!s)return;MAP.centerLat=s.lat;MAP.centerLon=s.lon;renderMap()}
async function copySelectedCoordinates(){const s=currentSite();if(!s)return;const text=`${s.lat.toFixed(6)}, ${s.lon.toFixed(6)}`;const b=safe('copySiteCoords');try{await navigator.clipboard.writeText(text);if(b){b.textContent=tr('Coordinates copied','Coordenadas copiadas');setTimeout(()=>b.textContent=tr('Copy coordinates','Copiar coordenadas'),1200)}}catch{window.prompt(tr('Copy coordinates','Copiar coordenadas'),text)}}
function bindMap(){
  const el=safe('geoMap');if(!el)return;safe('mapZoomIn').onclick=()=>{MAP.zoom=clamp(MAP.zoom+1,5,11);renderMap()};safe('mapZoomOut').onclick=()=>{MAP.zoom=clamp(MAP.zoom-1,5,11);renderMap()};safe('mapSatellite').onclick=()=>{MAP.style='satellite';renderMap()};safe('mapStandard').onclick=()=>{MAP.style='standard';renderMap()};safe('centerSelectedSite').onclick=centerSelectedSite;safe('copySiteCoords').onclick=copySelectedCoordinates;
  el.addEventListener('mousemove',e=>{const r=el.getBoundingClientRect(),c=worldPx(MAP.centerLat,MAP.centerLon,MAP.zoom),p=pxToLatLon(c.x+(e.clientX-r.left-r.width/2),c.y+(e.clientY-r.top-r.height/2),MAP.zoom);safe('mapCursor').textContent=`${p.lat.toFixed(4)}° N · ${Math.abs(p.lon).toFixed(4)}° ${p.lon<0?'W':'E'}`;if(MAP.dragging&&MAP.start){const dx=e.clientX-MAP.start.x,dy=e.clientY-MAP.start.y,start=worldPx(MAP.start.lat,MAP.start.lon,MAP.zoom),ll=pxToLatLon(start.x-dx,start.y-dy,MAP.zoom);MAP.centerLat=ll.lat;MAP.centerLon=ll.lon;renderMap()}});
  el.addEventListener('mousedown',e=>{if(e.target.closest('.map-site-pin'))return;MAP.dragging=true;MAP.start={x:e.clientX,y:e.clientY,lat:MAP.centerLat,lon:MAP.centerLon};el.classList.add('dragging')});window.addEventListener('mouseup',e=>{if(!MAP.dragging)return;const moved=MAP.start&&Math.hypot(e.clientX-MAP.start.x,e.clientY-MAP.start.y)>6;MAP.dragging=false;el.classList.remove('dragging');if(!moved&&MAP.start){const r=el.getBoundingClientRect(),c=worldPx(MAP.centerLat,MAP.centerLon,MAP.zoom),ll=pxToLatLon(c.x+(e.clientX-r.left-r.width/2),c.y+(e.clientY-r.top-r.height/2),MAP.zoom);if(ll.lat>42.6&&ll.lat<45.2&&ll.lon>-7&&ll.lon<-1.5){MAP.custom=previewPoint(ll.lat,ll.lon);S.site='custom';renderMap();renderSiteDetail()}}MAP.start=null});
  window.addEventListener('resize',()=>renderMap(),{passive:true});renderMap();
}

