// --- Technology explorer ----------------------------------------------------------------------
function techText(item,field){if(!item)return'—';const value=S.lang==='es'?(item[`${field}_es`]??item[field]):item[field];return value===null||value===undefined||value===''?'—':value}
function scoreLabel(key){const labels=technology.meta?.score_labels?.[key];if(Array.isArray(labels))return S.lang==='es'?labels[1]:labels[0];return ({scale_fit:tr('Scale fit','Encaje de escala'),dynamic_fit:tr('Dynamic operation','Operación dinámica'),maturity:tr('Technology maturity','Madurez tecnológica'),offshore_integration:tr('Offshore integration','Integración offshore'),pressure_or_integration:tr('Pressure / process integration','Presión / integración de proceso'),evidence:tr('Evidence completeness','Completitud de evidencia')})[key]||key}
function renderTechScoreMethod(){const box=safe('techScoreWeights'),p=safe('techScoreExplainer');if(!box)return;const weights=technology.meta?.score_weights||{};box.innerHTML=Object.entries(weights).map(([k,v])=>`<div class="fit-weight"><span>${scoreLabel(k)}</span><i><b style="--w:${v*100}%"></b></i><strong>${fmt(v*100,0)}%</strong></div>`).join('');if(p)p.textContent=S.lang==='es'?(technology.meta?.score_explainer_es||tr('The same weights are applied to every candidate. This is a concept-fit score, not a procurement recommendation, bankability rating or vendor guarantee.','Se aplican los mismos pesos a todos los candidatos. Es una puntuación de encaje conceptual, no una recomendación de compra, una valoración de bancabilidad ni una garantía del proveedor.')):(technology.meta?.score_explainer||'The same weights are applied to every candidate. This is a concept-fit score, not a procurement recommendation, bankability rating or vendor guarantee.')}
function techScore(item){const w=technology.meta?.score_weights||{scale_fit:.25,dynamic_fit:.2,maturity:.2,offshore_integration:.15,pressure_or_integration:.1,evidence:.1};return Math.round(Object.entries(w).reduce((a,[k,v])=>a+(item.score?.[k]||0)*v,0))}
function techCategoryName(c){return({electrolysis:tr('Electrolysis','Electrólisis'),methanol:tr('Methanol synthesis','Síntesis de metanol'),dac:tr('Direct air capture','Captura directa del aire'),water:tr('Water treatment','Tratamiento de agua')})[c]||c}
function renderTechnology(){
  const listEl=safe('techList');if(!listEl||!technology.items)return;document.querySelectorAll('[data-techcat]').forEach(b=>b.classList.toggle('active',b.dataset.techcat===techCategory));const q=(safe('techSearch')?.value||'').toLowerCase(),sort=safe('techSort')?.value||'score';let arr=technology.items.filter(x=>x.category===techCategory&&(!q||`${x.vendor} ${x.model} ${x.technology}`.toLowerCase().includes(q)));
  arr.sort((a,b)=>sort==='vendor'?a.vendor.localeCompare(b.vendor):sort==='scale'?((b.power_mw||0)-(a.power_mw||0)):techScore(b)-techScore(a));safe('techCount').textContent=`${arr.length} ${tr('candidates','candidatos')}`;safe('techCategoryTitle').textContent=`${techCategoryName(techCategory)} · ${tr('ranked candidates','candidatos priorizados')}`;
  listEl.innerHTML=arr.map((x,i)=>`<button class="tech-row ${selectedTechId===x.id?'active':''} ${chosenTech[x.category]===x.id?'chosen':''} ${Object.values(techCompare).includes(x.id)?'compared':''}" data-tech-id="${x.id}" type="button"><span class="rank">${chosenTech[x.category]===x.id?'✓':String(i+1).padStart(2,'0')}</span><span class="tech-name"><b>${x.vendor}</b><small>${x.model} · ${x.technology}</small></span><span class="tech-scale">${x.power_mw?`${fmt(x.power_mw,1)} MW`:techText(x,'capacity')}</span><span class="fit-score"><b>${techScore(x)}</b><small>/100</small></span></button>`).join('')||`<div class="empty-state">${tr('No candidates match this filter.','No hay candidatos para este filtro.')}</div>`;
  listEl.querySelectorAll('[data-tech-id]').forEach(b=>b.onclick=()=>{selectedTechId=b.dataset.techId;renderTechnology();renderTechDetail()});if(!selectedTechId||!technology.items.some(x=>x.id===selectedTechId&&x.category===techCategory)){selectedTechId=arr[0]?.id||null}renderTechDetail();renderTechScoreMethod();const note=technology.category_benchmarks?.[techCategory];if(note)safe('techCostNote').textContent=S.lang==='es'?note.cost_note_es:note.cost_note;renderTechComparison();
}
function spec(label,value){return value!==null&&value!==undefined&&value!==''?`<div><small>${label}</small><b>${value}</b></div>`:''}
function renderTechDetail(){
  const el=safe('techDetail'),x=technology.items?.find(i=>i.id===selectedTechId);if(!el||!x)return;
  const score=techScore(x),hasSupportedNumeric=x.category==='electrolysis'&&Number.isFinite(x.specific_kwh_kg),isChosen=chosenTech[x.category]===x.id;
  el.innerHTML=`<div class="tech-detail-head"><div><span class="kicker">${techCategoryName(x.category).toUpperCase()}</span><h3>${x.vendor}<br><span>${x.model}</span></h3></div><div class="score-ring compact"><strong>${score}</strong><span>/100</span></div></div>
  <div class="tech-spec-grid">${spec(tr('Technology','Tecnología'),x.technology)}${spec(tr('Module power','Potencia módulo'),x.power_mw?`${fmt(x.power_mw,2)} MW`:x.capacity)}${spec(tr('H₂ output','Producción H₂'),x.production_kg_h?`${fmt(x.production_kg_h,1)} kg/h`:null)}${spec(tr('Specific energy','Energía específica'),x.specific_kwh_kg?`${fmt(x.specific_kwh_kg,1)} kWh/kg H₂`:null)}${spec(tr('Outlet pressure','Presión salida'),x.pressure_barg!==null&&x.pressure_barg!==undefined?`${x.pressure_barg} barg`:null)}${spec(tr('Turndown / flexibility','Turndown / flexibilidad'),techText(x,'turndown'))}${spec(tr('Purity','Pureza'),techText(x,'purity'))}${spec(tr('Footprint','Huella'),techText(x,'footprint'))}${spec(tr('Maturity','Madurez'),techText(x,'maturity'))}</div>
  <div class="tech-rationale"><b>${tr('Offshore integration note','Nota de integración offshore')}</b><p>${S.lang==='es'?(x.offshore_note_es||x.integration_es||x.integration||x.offshore_note):(x.offshore_note||x.integration||'—')}</p>${x.thesis_relation?`<p class="thesis-link"><b>${tr('Thesis link:','Relación con el TFG:')}</b> ${S.lang==='es'?(x.thesis_relation_es||x.thesis_relation):x.thesis_relation}</p>`:''}</div>
  <div class="vendor-price"><span>${tr('Vendor price','Precio proveedor')}</span><b>${tr('Not publicly listed · quote required','No publicado · requiere oferta')}</b></div>
  <div class="tech-selection-note ${isChosen?'selected':''}"><b>${isChosen?'✓ '+tr('Selected for concept configuration','Seleccionado para la configuración conceptual'):tr('Configuration selection','Selección de configuración')}</b><span>${hasSupportedNumeric?tr('A public specific-energy value is available and can also update the scenario.','Existe un valor público de energía específica y puede actualizar también el escenario.'):tr('Selection is recorded without inventing an unsupported numeric performance value.','La selección se registra sin inventar un rendimiento numérico no soportado.')}</span></div>
  <div class="tech-compare-actions"><span>${tr('Add to comparison','Añadir a comparación')}</span>${['A','B','C'].map(k=>`<button type="button" data-tech-compare="${k}" class="${techCompare[k]===x.id?'active':''}">${k}</button>`).join('')}</div>
  <div class="tech-links"><a href="${x.manufacturer_url}" target="_blank" rel="noreferrer">${tr('Manufacturer','Fabricante')} ↗</a><a href="${x.datasheet_url}" target="_blank" rel="noreferrer">${tr('Datasheet / technical page','Ficha / página técnica')} ↗</a><button id="useTechBtn" type="button">${isChosen?tr('Selected ✓','Seleccionado ✓'):(hasSupportedNumeric?tr('Select + apply supported value','Seleccionar + aplicar valor soportado'):tr('Select for configuration','Seleccionar para configuración'))}</button></div>
  <div class="source-chips">${(x.source_ids||[]).map(s=>`<a href="#sources">${s}</a>`).join('')}</div>`;
  safe('useTechBtn')?.addEventListener('click',()=>selectTechnology(x));
  el.querySelectorAll('[data-tech-compare]').forEach(b=>b.addEventListener('click',()=>saveTechCompare(b.dataset.techCompare,x)));
}
function selectTechnology(x){
  chosenTech[x.category]=x.id;localStorage.setItem('methanor-tech-selection',JSON.stringify(chosenTech));
  let changed='';
  if(x.category==='electrolysis'&&Number.isFinite(x.specific_kwh_kg)){S.pem=x.specific_kwh_kg;changed=`PEM = ${x.specific_kwh_kg} kWh/kg H₂`;syncInputs();update()}
  renderTechnology();renderMassSpace();
  const b=safe('useTechBtn');if(b){b.textContent=`✓ ${tr('Selected','Seleccionado')}${changed?` · ${changed}`:''}`;}
}
function selectedTechnologyPayload(){
  const out={};Object.entries(chosenTech).forEach(([cat,id])=>{if(id)out[cat]=technology.items.find(x=>x.id===id)||null});return out;
}
function saveTechCompare(slot,item){if(!['A','B','C'].includes(slot)||!item)return;const existing=Object.values(techCompare).map(id=>technology.items?.find(x=>x.id===id)).filter(Boolean);if(existing.some(x=>x.category!==item.category))techCompare={A:null,B:null,C:null};techCompare[slot]=item.id;localStorage.setItem('methanor-tech-compare',JSON.stringify(techCompare));renderTechnology();renderTechComparison()}
function clearTechComparison(){techCompare={A:null,B:null,C:null};localStorage.removeItem('methanor-tech-compare');renderTechnology();renderTechComparison()}
function techDisplayValue(x,key){if(!x)return '—';if(key==='score')return `${techScore(x)}/100`;if(key==='module')return x.power_mw?`${fmt(x.power_mw,2)} MW`:(techText(x,'capacity')||tr('Not published','No publicado'));if(key==='energy')return Number.isFinite(x.specific_kwh_kg)?`${fmt(x.specific_kwh_kg,1)} kWh/kg H₂`:'—';if(key==='output')return Number.isFinite(x.production_kg_h)?`${fmt(x.production_kg_h,1)} kg/h`:'—';if(key==='pressure')return x.pressure_barg!==null&&x.pressure_barg!==undefined?`${x.pressure_barg} barg`:'—';if(key==='turndown')return techText(x,'turndown');if(key==='maturity')return techText(x,'maturity');return '—'}
function renderTechComparison(){const el=safe('techComparison');if(!el)return;const cols=['A','B','C'].map(k=>[k,technology.items?.find(x=>x.id===techCompare[k])]).filter(x=>x[1]&&x[1].category===techCategory);if(!cols.length){el.innerHTML=`<div class="empty-state compact-empty"><span>${tr('No technology candidates saved for comparison yet.','Aún no hay candidatos tecnológicos guardados para comparar.')}</span></div>`;return}const rows=[[tr('Vendor','Proveedor'),x=>x.vendor],[tr('Technology','Tecnología'),x=>x.technology],[tr('Portfolio fit','Encaje con el concepto'),x=>techDisplayValue(x,'score')],[tr('Module / capacity','Módulo / capacidad'),x=>techDisplayValue(x,'module')],[tr('Specific energy','Energía específica'),x=>techDisplayValue(x,'energy')],[tr('H₂ output','Producción H₂'),x=>techDisplayValue(x,'output')],[tr('Outlet pressure','Presión salida'),x=>techDisplayValue(x,'pressure')],[tr('Turndown','Turndown'),x=>techDisplayValue(x,'turndown')],[tr('Maturity','Madurez'),x=>techDisplayValue(x,'maturity')],[tr('Vendor price','Precio proveedor'),x=>tr('Quote required','Requiere oferta')]];el.innerHTML=`<div class="tech-compare-table" style="--cols:${cols.length}"><div class="tech-compare-th metric"></div>${cols.map(([k,x])=>`<div class="tech-compare-th"><span>${k}</span><b>${x.vendor}</b><small>${x.model}</small></div>`).join('')}${rows.map(([n,f])=>`<div class="tech-compare-td metric">${n}</div>${cols.map(([,x])=>`<div class="tech-compare-td">${f(x)}</div>`).join('')}`).join('')}</div>`}
function renderMassSpace(){if(!massSpace||!safe('massBars'))return;const total=massSpace.items.reduce((a,x)=>a+x.mass_t,0),moment=massSpace.items.reduce((a,x)=>a+x.moment_tm,0),kg=moment/total,closure=massSpace.displacement_t-total;safe('massTotal').textContent=fmt(total,0);safe('momentTotal').textContent=fmt(moment,0);safe('kgDerived').textContent=fmt(kg,2);safe('massClosure').textContent=(closure>=0?'+':'')+fmt(closure,0);const by={};massSpace.items.forEach(x=>by[x.category]=(by[x.category]||0)+x.mass_t);const labels={structure:['Structure','Estructura'],ballast:['Ballast','Lastre'],liquid:['Stored liquid','Líquido almacenado'],mooring:['Mooring','Fondeo'],turbine:['Turbine','Turbina'],process:['Process plant','Planta de proceso'],operations:['Operations','Operaciones']};safe('massBars').innerHTML=Object.entries(by).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="mass-row"><span>${tr(...(labels[k]||[k,k]))}</span><i style="--w:${v/total*100}%"></i><b>${fmt(v,0)} t · ${fmt(v/total*100,1)}%</b></div>`).join('');safe('spaceTable').innerHTML=massSpace.space_items.map(x=>`<div class="space-row"><span><b>${S.lang==='es'?x.name_es:x.name}</b><small>${S.lang==='es'?(x.status==='Academic baseline'?'Referencia académica':x.status==='Length only — footprint not stated'?'Solo longitud — huella no indicada':x.status):x.status}</small></span><strong>${x.area_m2?`${fmt(x.area_m2,1)} m²`:tr('footprint not stated','huella no indicada')}</strong></div>`).join('');const known=massSpace.space_items.reduce((a,x)=>a+(x.area_m2||0),0),d0=massSpace.deck_reference[0].area_m2,d1=massSpace.deck_reference[1].area_m2;safe('deck0Use').textContent=`${fmt(known,1)} / ${fmt(d0,0)} m² (${fmt(known/d0*100,1)}%)`;safe('deck1Use').textContent=`${fmt(known,1)} / ${fmt(d1,0)} m² (${fmt(known/d1*100,1)}%)`;safe('massWarning').textContent=S.lang==='es'?massSpace.warning_es:massSpace.warning}

// --- Risk register -----------------------------------------------------------------------------
function dynamicRisk(r){let p=r.probability,i=r.impact;if(r.id==='R01'&&S.meanWind<8.2)p=Math.min(5,p+1);if(r.id==='R15'&&S.capex>1200)p=Math.min(5,p+1);if(r.id==='R16'&&S.price<1000)p=Math.min(5,p+1);if(r.id==='R17'&&S.wacc>.1)p=Math.min(5,p+1);const s=currentSite();if(r.id==='R02'&&s?.depth_m>150)p=Math.min(5,p+1);return{...r,probability:p,impact:i,severity:p*i}}
function severityClass(v){return v>=20?'critical':v>=12?'high':v>=6?'medium':'low'}
function riskCategoryName(c){const m={Resource:['Resource','Recurso'],Marine:['Marine','Marino'],Regulatory:['Regulatory','Regulatorio'],Environmental:['Environmental','Ambiental'],Process:['Process','Proceso'],Safety:['Safety','Seguridad'],Naval:['Naval','Naval'],Delivery:['Delivery','Ejecución'],Commercial:['Commercial','Comercial'],Operations:['Operations','Operaciones'],Finance:['Finance','Finanzas'],Data:['Data','Datos']};return m[c]?tr(...m[c]):c}
function renderRisks(){if(!risks.length||!safe('riskMatrix'))return;const rr=risks.map(dynamicRisk),cats=[...new Set(rr.map(x=>x.category))].sort(),sel=safe('riskFilter');if(sel){const wanted=riskCategory;sel.innerHTML=`<option value="all">${tr('All categories','Todas las categorías')}</option>`+cats.map(c=>`<option value="${c}">${riskCategoryName(c)}</option>`).join('');sel.value=wanted}let cells='';for(let impact=5;impact>=1;impact--){for(let prob=1;prob<=5;prob++){const here=rr.filter(x=>x.impact===impact&&x.probability===prob);cells+=`<div class="risk-cell ${severityClass(prob*impact)}" data-p="${prob}" data-i="${impact}"><span>${impact}×${prob}</span>${here.map(x=>`<i title="${x.id} · ${S.lang==='es'?x.title_es:x.title}">${x.id}</i>`).join('')}</div>`}}safe('riskMatrix').innerHTML=cells;let list=rr.filter(x=>riskCategory==='all'||x.category===riskCategory).sort((a,b)=>b.severity-a.severity);safe('riskList').innerHTML=list.map(r=>`<details class="risk-row"><summary><span class="risk-id">${r.id}</span><span><b>${S.lang==='es'?r.title_es:r.title}</b><small>${riskCategoryName(r.category)} · P${r.probability} × I${r.impact}</small></span><em class="${severityClass(r.severity)}">${r.severity}/25</em></summary><p><b>${tr('Mitigation','Mitigación')}:</b> ${S.lang==='es'?r.mitigation_es:r.mitigation}</p><p class="risk-evidence">${tr('Evidence / next gate','Evidencia / siguiente hito')}: ${r.evidence}</p></details>`).join('');const critical=rr.filter(x=>x.severity>=20).length,high=rr.filter(x=>x.severity>=12).length;safe('riskHeadline').textContent=`${critical} ${tr('critical','críticos')} · ${high} ${tr('high','altos')}`}

// --- Scenarios ---------------------------------------------------------------------------------
function snapshot(){return{turbineCount:S.turbineCount,meanWind:S.meanWind,weibullK:S.weibullK,availability:S.availability,pem:S.pem,dac:S.dac,synth:S.synth,water:S.water,bop:S.bop,capex:S.capex,opex:S.opex,price:S.price,grant:S.grant,wacc:S.wacc,life:S.life,degradation:S.degradation,decom:S.decom}}
function saveSlot(slot){const state=snapshot(),results=project(state);scenarioSlots[slot]={state,results,ts:new Date().toISOString()};localStorage.setItem(`methanor-scenario-${slot}`,JSON.stringify(scenarioSlots[slot]));renderScenarioComparison()}
function loadScenarioSlots(){['A','B','C'].forEach(k=>{try{const x=JSON.parse(localStorage.getItem(`methanor-scenario-${k}`));if(x?.state)scenarioSlots[k]=x}catch{}})}
function renderScenarioComparison(){const el=safe('scenarioComparison');if(!el)return;const cur={state:snapshot(),results:currentProject()},cols=[['NOW',cur],...['A','B','C'].map(k=>[k,scenarioSlots[k]]).filter(x=>x[1])];const rows=[[tr('e-MeOH','e-MeOH'),x=>`${fmt(x.results.meoh,0)} t/y`],[tr('Mean wind','Viento medio'),x=>`${fmt(x.state.meanWind,2)} m/s`],[tr('CAPEX','CAPEX'),x=>`€${fmt(x.state.capex,0)} M`],[tr('OPEX','OPEX'),x=>`€${fmt(x.state.opex,0)} M/y`],[tr('NPV','VAN'),x=>`${x.results.npv>=0?'+':''}${fmt(x.results.npv,0)} M€`],[tr('IRR','TIR'),x=>x.results.irr==null?'n/a':pct(x.results.irr,1)],[tr('LCOeM','LCOeM'),x=>`${fmt(x.results.lcoe,0)} €/t`],[tr('Payback','Retorno'),x=>x.results.pay==null?'>25 y':`${fmt(x.results.pay,1)} y`]];el.innerHTML=`<div class="scenario-table" style="--cols:${cols.length}"><div class="scenario-th metric-name"></div>${cols.map(c=>`<div class="scenario-th">${c[0]}</div>`).join('')}${rows.map(([n,f])=>`<div class="scenario-td metric-name">${n}</div>${cols.map(c=>`<div class="scenario-td ${n===tr('NPV','VAN')?(c[1].results.npv>=0?'positive':'negative'):''}">${f(c[1])}</div>`).join('')}`).join('')}</div>${cols.length===1?`<div class="quality-note">${tr('Save A, B or C to compare alternative assumptions side by side.','Guarda A, B o C para comparar supuestos alternativos lado a lado.')}</div>`:''}`}

// --- Evidence & decision logic -----------------------------------------------------------------
function sourceModuleName(v){const m={'Home':['Home','Inicio'],'Site':['Site','Emplazamiento'],'P2X':['P2X','P2X'],'Technology':['Technology','Tecnología'],'Platform':['Platform','Plataforma'],'Build & Ops':['Build & Ops','Construcción y O&M'],'Economics':['Economics','Economía'],'Methodology':['Methodology','Metodología'],'Evidence':['Evidence','Evidencia'],'Origin':['Origin','Origen']};return m[v]?tr(...m[v]):v}
function sourceVariableName(v){const m={'turbine rating':'potencia nominal','rotor diameter':'diámetro de rotor','hub height':'altura de buje','cut-in/rated/cut-out':'cut-in/nominal/cut-out','PEM electricity intensity':'intensidad eléctrica PEM','stack/system efficiency':'eficiencia stack/sistema','lifetime':'vida útil','renewable methanol pathway':'ruta de metanol renovable','cost context':'contexto de costes','process framing':'marco de proceso','wind speed':'velocidad de viento','significant wave height':'altura significativa de ola','wave period':'periodo de ola','water depth':'profundidad','bathymetry':'batimetría','coastline':'línea de costa','spatial planning':'ordenación espacial','priority uses':'usos prioritarios','permitting screening':'cribado de permisos','wave observations':'observaciones de oleaje','sea level':'nivel del mar','currents':'corrientes','metocean validation':'validación metoceánica','offshore wind CAPEX':'CAPEX eólico offshore','O&M':'O&M','capacity factor':'factor de capacidad','LCOE methodology':'metodología LCOE','DAC maturity':'madurez DAC','DAC energy and cost uncertainty':'incertidumbre energética y de coste DAC','site baseline':'referencia de emplazamiento','displacement':'desplazamiento','draft':'calado','air gap':'air gap','GM':'GM','original financial assumptions':'supuestos financieros originales','basemap':'mapa base','imagery basemap':'mapa base de imagen'};return S.lang==='es'?(m[v]||v):v}
function sourceDate(s){const accessed=s.accessed?new Date(`${s.accessed}T00:00:00Z`):null,accessTxt=accessed?accessed.toLocaleDateString(S.lang==='es'?'es-ES':'en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}):'';if(s.published_year)return `${tr('Published','Publicado')} ${s.published_year}${accessTxt?` · ${tr('Accessed','Consultado')} ${accessTxt}`:''}`;return accessTxt?`${tr('Accessed','Consultado')} ${accessTxt}`:(s.year?`${tr('Reference year','Año de referencia')} ${s.year}`:'')}
function renderSources(filter=''){const el=safe('sourceTable');if(!el)return;const q=filter.trim().toLowerCase(),list=sources.filter(s=>!q||[s.id,s.title,s.title_es,s.organization,s.use,s.use_es,s.quality,...(s.variables||[]),...(s.used_in||[])].filter(Boolean).join(' ').toLowerCase().includes(q));el.innerHTML=list.map(s=>{const title=S.lang==='es'?(s.title_es||s.title):s.title,use=S.lang==='es'?(s.use_es||s.use):s.use,conf=tr(s.confidence,s.confidence==='High'?'Alta':s.confidence==='Medium'?'Media':s.confidence==='Low'?'Baja':s.confidence);return `<div class="source-row"><span class="source-id">${s.id}</span><a href="${s.url}" ${s.url.startsWith('#')?'':'target="_blank" rel="noreferrer"'}>${title} ${s.url.startsWith('#')?'↘':'↗'}<div class="source-meta">${(s.variables||[]).slice(0,3).map(v=>`<i>${sourceVariableName(v)}</i>`).join('')}</div></a><span>${s.organization}<br><small class="source-date">${sourceDate(s)}</small></span><div><span>${use}</span><div class="source-meta">${(s.used_in||[]).map(v=>`<i>${sourceModuleName(v)}</i>`).join('')}</div></div><span class="source-confidence">${conf}</span></div>`}).join('')||`<div class="quality-note">${tr('No sources match this filter.','Ninguna fuente coincide con el filtro.')}</div>`}
const DECISIONS=[
 {id:'D01',title:['15 MW design unit vs 150 MW hub','Unidad de diseño de 15 MW vs hub de 150 MW'],rationale:['Preserve the naval thesis unit while enforcing the energy required by the target methanol output.','Conservar la unidad naval del TFG a la vez que se respeta la energía necesaria para la producción objetivo.'],alternatives:['Single 15 MW fully integrated unit; separate centralized P2X island.','Unidad integrada única de 15 MW; isla P2X centralizada separada.'],tradeoff:['Hub scale improves process utilization but adds collection, integration and CAPEX complexity.','La escala de hub mejora la utilización del proceso, pero añade complejidad de colección, integración y CAPEX.'],evidence:'S01 · S10'},
 {id:'D02',title:['PEM as editable baseline','PEM como baseline editable'],rationale:['Fast dynamics fit variable wind and the thesis lineage, while MethaNor exposes ALK, SOEC and AEM alternatives.','La dinámica rápida encaja con el viento variable y con el TFG, mientras MethaNor expone alternativas ALK, SOEC y AEM.'],alternatives:['Alkaline, SOEC, AEM.','Alcalina, SOEC, AEM.'],tradeoff:['PEM flexibility vs cost/critical materials; SOEC efficiency vs thermal-integration and maturity risk.','Flexibilidad PEM frente a coste/materiales críticos; eficiencia SOEC frente a integración térmica y madurez.'],evidence:'S02 · S11–S20'},
 {id:'D03',title:['DAC retained, but not privileged','DAC se mantiene, pero no se privilegia'],rationale:['It preserves autonomous offshore carbon supply, but its energy and integration penalty is made explicit.','Conserva suministro autónomo de carbono offshore, pero hace explícita su penalización energética e integración.'],alternatives:['Biogenic CO₂ import; point-source CO₂; hybrid supply.','Importación de CO₂ biogénico; CO₂ de fuente puntual; suministro híbrido.'],tradeoff:['Autonomy and additionality vs energy intensity, equipment footprint and maturity.','Autonomía y adicionalidad frente a intensidad energética, huella de equipo y madurez.'],evidence:'S09 · S27–S31'},
 {id:'D04',title:['Semisubmersible concept retained','Se conserva el concepto semisumergible'],rationale:['The portfolio objective is to evolve the thesis rather than silently replace its naval architecture.','El objetivo del proyecto es evolucionar el TFG, no sustituir silenciosamente su arquitectura naval.'],alternatives:['Spar, barge, TLP, separate floating wind + process vessel.','Spar, barcaza, TLP, eólica flotante + buque/plataforma de proceso separada.'],tradeoff:['Large deck area and stability potential vs structural weight, motions, moorings and fabrication complexity.','Gran superficie y potencial de estabilidad frente a peso estructural, movimientos, fondeo y complejidad de fabricación.'],evidence:'S10'},
 {id:'D05',title:['Seven-day methanol inventory baseline','Inventario base de metanol de siete días'],rationale:['Preserves the thesis mass register while the broader logistics concept remains a scenario choice.','Conserva el registro de pesos del TFG mientras la logística global sigue siendo una decisión de escenario.'],alternatives:['14-day buffer; shuttle frequency optimization; export pipeline.','Buffer de 14 días; optimización de shuttle; tubería de exportación.'],tradeoff:['More autonomy raises storage mass, hazardous inventory and deck/tank volume.','Más autonomía aumenta masa almacenada, inventario peligroso y volumen de tanque/cubierta.'],evidence:'S10'},
 {id:'D06',title:['No automatic vendor winner','No existe un ganador automático de proveedores'],rationale:['Public data are incomplete and commercial guarantees are project-specific; MethaNor ranks fit, not bankability.','Los datos públicos son incompletos y las garantías son específicas de cada proyecto; MethaNor ordena por encaje, no por aptitud para financiación.'],alternatives:['Hard-coded “best” supplier; cheapest-only ranking.','Proveedor «mejor» predefinido; clasificación basada solo en coste.'],tradeoff:['Transparent uncertainty is less flashy but much more defensible in an engineering portfolio.','La incertidumbre transparente es menos llamativa, pero mucho más defendible en un proyecto de ingeniería.'],evidence:'S11–S31'}
];
function renderDecisionLog(){const el=safe('decisionGrid');if(!el)return;el.innerHTML=DECISIONS.map(d=>`<article class="decision-card"><div><span>${d.id}</span><b>${d.title[S.lang==='es'?1:0]}</b></div><p><strong>${tr('Rationale','Justificación')}</strong>${d.rationale[S.lang==='es'?1:0]}</p><p><strong>${tr('Alternatives','Alternativas')}</strong>${d.alternatives[S.lang==='es'?1:0]}</p><p><strong>${tr('Trade-off','Compromiso')}</strong>${d.tradeoff[S.lang==='es'?1:0]}</p><small>${d.evidence}</small></article>`).join('')}

function outputs(){[['turbineCount','turbineCountOut',v=>v],['meanWind','meanWindOut',v=>`${(+v).toFixed(2)} m/s`],['availability','availabilityOut',v=>pct(v,1)],['pem','pemOut',v=>`${fmt(v,1)} kWh/kg`],['capex','capexOut',v=>`€${fmt(v,0)} M`],['opex','opexOut',v=>`€${fmt(v,0)} M`],['price','priceOut',v=>`€${fmt(v,0)}/t`],['grant','grantOut',v=>pct(v,0)],['wacc','waccOut',v=>pct(v,1)]].forEach(([id,o,f])=>{if(safe(o))safe(o).textContent=f(S[id])})}
function update(){const p=currentProject();setText(p);renderEnergy(p);renderCash(p);renderCosts(p);renderTornado(p);renderBreakEven();renderAllocations();renderSCurve();renderRisks();renderScenarioComparison();renderTechComparison();outputs()}
function syncInputs(){['turbineCount','meanWind','availability','pem','capex','opex','price','grant','wacc'].forEach(k=>{if(safe(k))safe(k).value=S[k]})}
function applyPreset(n){Object.assign(S,{...BASE,lang:S.lang,site:S.site});if(n==='conservative')Object.assign(S,{meanWind:8.1,availability:.90,pem:55,capex:1250,opex:42,price:900,grant:.20,wacc:.11});if(n==='optimistic')Object.assign(S,{meanWind:9.1,availability:.96,pem:49,capex:850,opex:27,price:1500,grant:.50,wacc:.055});syncInputs();update()}
function loadUrl(){const q=new URLSearchParams(location.search);['turbineCount','meanWind','availability','pem','capex','opex','price','grant','wacc'].forEach(k=>{if(q.has(k)&&Number.isFinite(+q.get(k)))S[k]=+q.get(k)});syncInputs()}
function bind(){
  ['turbineCount','meanWind','availability','pem','capex','opex','price','grant','wacc'].forEach(k=>safe(k)?.addEventListener('input',e=>{S[k]=+e.target.value;document.querySelectorAll('.preset-row button').forEach(b=>b.classList.remove('active'));update()}));
  safe('resetBtn').onclick=()=>{const keepLang=S.lang;Object.assign(S,BASE,{lang:keepLang});MAP.custom=null;S.site='cantabria-reference';chosenTech={electrolysis:null,methanol:null,dac:null,water:null};techCompare={A:null,B:null,C:null};localStorage.removeItem('methanor-tech-selection');localStorage.removeItem('methanor-tech-compare');syncInputs();document.querySelectorAll('.preset-row button').forEach(b=>b.classList.remove('active'));document.querySelector('[data-preset="base"]')?.classList.add('active');renderMap();renderSiteDetail();renderTechnology();renderMassSpace();update()};
  safe('exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify({version:'4.2',scenario:snapshot(),site:currentSite(),technology_selection:selectedTechnologyPayload(),technology_comparison:techCompare,results:currentProject(),break_even:breakEven(),scope:'Conceptual / pre-FEED screening only; no vendor quote or permitting conclusion'},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='methanor-scenario-v4.2.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
  safe('copyLinkBtn').onclick=async()=>{const u=new URL(location.href);Object.entries(snapshot()).forEach(([k,v])=>{if(['turbineCount','meanWind','availability','pem','capex','opex','price','grant','wacc'].includes(k))u.searchParams.set(k,v)});try{await navigator.clipboard.writeText(u.toString());safe('copyLinkBtn').textContent=tr('Copied','Copiado');setTimeout(()=>safe('copyLinkBtn').textContent=tr('Copy state','Copiar estado'),1200)}catch{window.prompt(tr('Copy scenario URL','Copia la URL del escenario'),u.toString())}};
  document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-preset]').forEach(x=>x.classList.remove('active'));b.classList.add('active');applyPreset(b.dataset.preset)});
  document.querySelectorAll('[data-platform-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-platform-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.platform-view').forEach(v=>v.classList.remove('active'));safe(`platform${b.dataset.platformView[0].toUpperCase()+b.dataset.platformView.slice(1)}`)?.classList.add('active')});
  safe('sourceSearch')?.addEventListener('input',e=>renderSources(e.target.value));safe('techSearch')?.addEventListener('input',renderTechnology);safe('techSort')?.addEventListener('change',renderTechnology);document.querySelectorAll('[data-techcat]').forEach(b=>b.onclick=()=>{techCategory=b.dataset.techcat;selectedTechId=null;renderTechnology()});
  safe('riskFilter')?.addEventListener('change',e=>{riskCategory=e.target.value;renderRisks()});safe('clearTechCompare')?.addEventListener('click',clearTechComparison);document.querySelectorAll('[data-save-slot]').forEach(b=>b.onclick=()=>saveSlot(b.dataset.saveSlot));safe('clearScenarios')?.addEventListener('click',()=>{['A','B','C'].forEach(k=>{scenarioSlots[k]=null;localStorage.removeItem(`methanor-scenario-${k}`)});renderScenarioComparison()});
  safe('langEn').onclick=()=>{S.lang='en';applyLanguage()};safe('langEs').onclick=()=>{S.lang='es';applyLanguage()};bindMap();
}
function observeNavigation(){if(!('IntersectionObserver'in window))return;const links=[...document.querySelectorAll('.topnav a[data-nav]')],byId=id=>links.find(a=>a.dataset.nav===id);const obs=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!visible)return;links.forEach(a=>a.classList.remove('active'));const l=byId(visible.target.id);if(l)l.classList.add('active')},{rootMargin:'-20% 0px -65% 0px',threshold:[0,.15,.35]});document.querySelectorAll('[data-section]').forEach(s=>obs.observe(s))}

async function init(){
  try{
    const [a,b,c,d,e]=await Promise.all([
      fetch('data/sites.json').then(r=>{if(!r.ok)throw new Error('sites.json');return r.json()}),
      fetch('data/sources.json').then(r=>{if(!r.ok)throw new Error('sources.json');return r.json()}),
      fetch('data/technology_catalog.json').then(r=>{if(!r.ok)throw new Error('technology_catalog.json');return r.json()}),
      fetch('data/risks.json').then(r=>{if(!r.ok)throw new Error('risks.json');return r.json()}),
      fetch('data/mass_space.json').then(r=>{if(!r.ok)throw new Error('mass_space.json');return r.json()})
    ]);sites=a;sources=b;technology=c;risks=d;massSpace=e;
  }catch(err){console.error('MethaNor data load failed',err);const box=safe('appError');if(box){box.hidden=false;box.textContent=tr('Data files could not be loaded. Run MethaNor through a local/static web server and refresh.','No se pudieron cargar los archivos de datos. Ejecuta MethaNor mediante un servidor web local/estático y recarga.')}}
  loadScenarioSlots();renderGantt();renderOps();renderPhaseStaffing();loadUrl();bind();renderSiteDetail();renderTechnology();renderTechComparison();renderMassSpace();renderRisks();renderScenarioComparison();renderDecisionLog();renderSources();update();observeNavigation();applyLanguage();
}
init();
